SELECT k.full_short_url,
       COALESCE(a.access_pv, 0) AS access_pv,
       COALESCE(t.today_pv, 0) AS today_pv
FROM (
    SELECT full_short_url FROM t_link_stats_today WHERE `date` = #{bizDate}
    UNION
    SELECT full_short_url FROM t_link_access_stats WHERE `date` = #{bizDate}
) k
LEFT JOIN (
    SELECT full_short_url, SUM(pv) AS access_pv
    FROM t_link_access_stats
    WHERE `date` = #{bizDate}
    GROUP BY full_short_url
) a ON a.full_short_url = k.full_short_url
LEFT JOIN t_link_stats_today t
    ON t.full_short_url = k.full_short_url
    AND t.`date` = #{bizDate}
